  1	import { expect, test } from "@playwright/test";
  2	
  3	test("live search preserves API ranking, spelling, duplicates and entity context", async ({
  4	  page,
  5	}) => {
  6	  const entities = [
  7	    { name: "john lewis partnership", kind: "Funder", funder_kind: "Company" },
  8	    { name: "John Cooper", kind: "MP", funder_kind: null },
  9	    { name: "John Kinder", kind: "Funder", funder_kind: "Individual" },
 10	    { name: "john lewis partnership", kind: "Funder", funder_kind: "Company" },
 11	    { name: "John Union", kind: "Funder", funder_kind: "Trade Union" },
 12	    { name: "John Trust", kind: "Funder", funder_kind: "Not Specified" },
 13	    { name: "John Foundation", kind: "Funder", funder_kind: null },
 14	  ];
 15	  const requests: URL[] = [];
 16	  await page.route("**/api/search?*", async (route) => {
 17	    requests.push(new URL(route.request().url()));
 18	    await route.fulfill({ json: { entities } });
 19	  });
 20	  await page.goto("/");
 21	  const input = page.getByRole("searchbox");
 22	  await input.fill("jo");
 23	  await expect(
 24	    page.getByText("Type 1 more character to search."),
 25	  ).toBeVisible();
 26	  await input.press("Enter");
 27	  expect(requests).toHaveLength(0);
 28	  await input.fill("  John  ");
 29	  await expect(
 30	    page.getByRole("heading", { name: "7 results shown" }),
 31	  ).toBeVisible();
 32	  expect(requests).toHaveLength(1);
 33	  expect(requests[0].searchParams.get("term")).toBe("John");
 34	  expect(requests[0].searchParams.get("max_entries")).toBe("10");
 35	  expect(requests[0].searchParams.get("strictness")).toBe("1");
 36	  await expect(page.locator(".entity-name")).toHaveText(
 37	    entities.map((entity) => entity.name),
 38	  );
 39	  await expect(page.locator(".entity-kind-label")).toHaveText([
 40	    "Company",
 41	    "Individual",
 42	    "Company",
 43	    "Trade union",
 44	    "Unclassified",
 45	    "Unclassified",
 46	  ]);
 47	  await expect(page.locator(".entity-kind-label").first()).toBeVisible();
 48	  await expect(
 49	    page.locator(".entity-row").nth(1).locator(".entity-kind"),
 50	  ).toHaveCount(0);
 51	  expect(
 52	    await page
 53	      .locator(".entity-indicator:not(.entity-kind) .entity-icon")
 54	      .evaluateAll((icons) =>
 55	        icons.map((icon) => icon.getAttribute("aria-label")),
 56	      ),
 57	  ).toEqual([
 58	    "Funder: Company",
 59	    "MP",
 60	    "Funder: Individual",
 61	    "Funder: Company",
 62	    "Funder: Trade union",
 63	    "Funder: Unclassified",
 64	    "Funder: Unclassified",
 65	  ]);
 66	  const individual = page.getByRole("button", {
 67	    name: "Funder: Individual",
 68	    exact: true,
 69	  });
 70	  await individual.focus();
 71	  await expect(page.locator(".entity-tooltip")).toHaveText(
 72	    "Funder: Individual",
 73	  );
 74	  await individual.press("Escape");
 75	  await expect(page.locator(".entity-tooltip")).toHaveCount(0);
 76	  await individual.blur();
 77	  await individual.hover();
 78	  await expect(page.locator(".entity-tooltip")).toHaveText(
 79	    "Funder: Individual",
 80	  );
 81	  await page.locator(".entity-tooltip").hover();
 82	  await expect(page.locator(".entity-tooltip")).toBeVisible();
 83	  await input.hover();
 84	  await expect(page.locator(".entity-tooltip")).toHaveCount(0);
 85	  await expect(page.locator("mark").first()).toHaveText("john");
 86	  await expect(page).toHaveURL(/q=John/);
 87	});
 88	
 89	test("a late response cannot replace a newer query or repopulate a cleared search", async ({
 90	  page,
 91	}) => {
 92	  let releaseOld: () => void = () => {};
 93	  let finishOld: () => void = () => {};
 94	  const oldResponse = new Promise<void>((resolve) => {
 95	    releaseOld = resolve;
 96	  });
 97	  const oldHandled = new Promise<void>((resolve) => {
 98	    finishOld = resolve;
 99	  });
100	  await page.route("**/api/search?*", async (route) => {
101	    const term = new URL(route.request().url()).searchParams.get("term");
102	    if (term === "John") await oldResponse;
103	    await route.fulfill({
104	      json: {
105	        entities: [
106	          {
107	            name: term === "John" ? "John Cooper" : "hsbc uk bank plc",
108	            kind: "Funder",
109	            funder_kind: "Company",
110	          },
111	        ],
112	      },
113	    });
114	    if (term === "John") finishOld();
115	  });
116	  await page.goto("/");
117	  const input = page.getByRole("searchbox");
118	  const oldRequest = page.waitForRequest((request) =>
119	    request.url().includes("term=John"),
120	  );
121	  await input.fill("John");
122	  await oldRequest;
123	  await input.fill("HSBC");
124	  await expect(page.locator(".entity-name")).toHaveText("hsbc uk bank plc");
125	  releaseOld();
126	  await oldHandled;
127	  await expect(page.locator(".entity-name")).toHaveText("hsbc uk bank plc");
128	  await expect(page.getByText("John Cooper", { exact: true })).toHaveCount(0);
129	  await page.getByRole("button", { name: "Clear search" }).click();
130	  await expect(input).toHaveValue("");
131	  await expect(
132	    page.getByRole("heading", { name: "Start with a name" }),
133	  ).toBeVisible();
134	  await expect(page.locator(".entity-row")).toHaveCount(0);
135	  await expect(input).toBeFocused();
136	  await expect(page).not.toHaveURL(/q=/);
137	});
138	
139	test("an unavailable service offers retry and an empty response offers a useful next step", async ({
140	  page,
141	}) => {
142	  let calls = 0;
143	  await page.route("**/api/search?*", async (route) => {
144	    calls += 1;
145	    if (calls === 1)
146	      await route.fulfill({ status: 503, body: "service unavailable" });
147	    else await route.fulfill({ json: { entities: [] } });
148	  });
149	  await page.goto("/?q=unknown");
150	  await expect(page.getByRole("alert")).toContainText("Search couldn’t load");
151	  await page.getByRole("button", { name: "Try again" }).click();
152	  await expect(
153	    page.getByRole("heading", { name: "No matches for “unknown”" }),
154	  ).toBeVisible();
155	  await expect(
156	    page.getByText(
157	      "Try a surname, a shorter company name, or a different spelling.",
158	    ),
159	  ).toBeVisible();
160	  await page.getByRole("button", { name: "Edit your search" }).click();
161	  await expect(page.getByRole("searchbox")).toBeFocused();
162	  expect(calls).toBe(2);
163	});
164	
165	test("search text and names containing markup or regular expression syntax remain literal", async ({
166	  page,
167	}) => {
168	  const name = 'A.* <img src=x onerror="alert(1)"> & Co';
169	  await page.route("**/api/search?*", (route) =>
170	    route.fulfill({
171	      json: { entities: [{ name, kind: "Funder", funder_kind: "Company" }] },
172	    }),
173	  );
174	  await page.goto("/");
175	  await page.getByRole("searchbox").fill("A.*");
176	  await expect(page.locator(".entity-name")).toHaveText(name);
177	  await expect(page.locator(".entity-name mark")).toHaveText("A.*");
178	  await expect(page.locator(".entity-name img")).toHaveCount(0);
179	});
180	
181	test("keyboard search and long results remain usable on a narrow screen", async ({
182	  page,
183	}) => {
184	  await page.setViewportSize({ width: 360, height: 780 });
185	  await page.route("**/api/search?*", (route) =>
186	    route.fulfill({
187	      json: {
188	        entities: [
189	          {
190	            name: "Association of Research and Public Interest Organisations of the United Kingdom",
191	            kind: "Funder",
192	            funder_kind: "Unincorporated association",
193	          },
194	        ],
195	      },
196	    }),
197	  );
198	  await page.goto("/");
199	  await page.keyboard.press("/");
200	  await expect(page.getByRole("searchbox")).toBeFocused();
201	  await page.getByRole("searchbox").fill("Association");
202	  await expect(
203	    page.getByRole("button", { name: "Funder: Unincorporated association" }),
204	  ).toBeVisible();
205	  await expect(page.locator(".entity-kind-label")).toHaveText(
206	    "Unincorporated association",
207	  );
208	  await expect(page.locator(".entity-kind-label")).toBeVisible();
209	  await expect(page.locator(".entity-kind")).toBeVisible();
210	  expect(
211	    await page.evaluate(
212	      () => document.documentElement.scrollWidth <= window.innerWidth,
213	    ),
214	  ).toBe(true);
215	  await page.keyboard.press("Escape");
216	  await expect(page.getByRole("searchbox")).toHaveValue("");
217	});

