  1	// Search defaults live here. The API applies
  2	// max_entries independently to MPs and funders, then merges by similarity.
  3	export const searchConfiguration = {
  4	  minimumCharacters: 3,
  5	  debounceMs: 250,
  6	  maxEntriesPerType: 10,
  7	  strictness: 1,
  8	  timeoutMs: 10_000,
  9	};
 10	
 11	export function readStrictness(value: string | null): number {
 12	  if (!value?.trim()) return searchConfiguration.strictness;
 13	  const parsed = Number(value);
 14	  return Number.isFinite(parsed) && parsed >= 0 && parsed <= 1
 15	    ? Math.round(parsed * 100) / 100
 16	    : searchConfiguration.strictness;
 17	}
 18	
 19	export interface Entity {
 20	  name: string;
 21	  kind: "MP" | "Funder";
 22	  funderKind: string | null;
 23	}
 24	
 25	function isRecord(value: unknown): value is Record<string, unknown> {
 26	  return typeof value === "object" && value !== null;
 27	}
 28	
 29	function readEntities(body: unknown): Entity[] {
 30	  if (!isRecord(body) || !Array.isArray(body.entities)) {
 31	    throw new Error("Search returned an unexpected response. Try again.");
 32	  }
 33	
 34	  return body.entities.map((value: unknown) => {
 35	    if (
 36	      !isRecord(value) ||
 37	      typeof value.name !== "string" ||
 38	      (value.kind !== "MP" && value.kind !== "Funder") ||
 39	      (value.funder_kind !== null && typeof value.funder_kind !== "string")
 40	    ) {
 41	      throw new Error("Search returned an unexpected response. Try again.");
 42	    }
 43	    return {
 44	      name: value.name,
 45	      kind: value.kind,
 46	      funderKind: value.funder_kind,
 47	    };
 48	  });
 49	}
 50	
 51	export async function searchEntities(
 52	  term: string,
 53	  signal: AbortSignal,
 54	  strictness: number,
 55	): Promise<Entity[]> {
 56	  const controller = new AbortController();
 57	  let timedOut = false;
 58	  const cancel = () => controller.abort();
 59	  signal.addEventListener("abort", cancel, { once: true });
 60	  if (signal.aborted) cancel();
 61	  const timeout = setTimeout(() => {
 62	    timedOut = true;
 63	    controller.abort();
 64	  }, searchConfiguration.timeoutMs);
 65	
 66	  try {
 67	    const params = new URLSearchParams({
 68	      term,
 69	      max_entries: String(searchConfiguration.maxEntriesPerType),
 70	      strictness: String(strictness),
 71	    });
 72	    const response = await fetch(`/api/search?${params}`, {
 73	      signal: controller.signal,
 74	    });
 75	    if (!response.ok) {
 76	      throw new Error(
 77	        "The search service is unavailable. Try again in a moment.",
 78	      );
 79	    }
 80	    const body: unknown = await response.json();
 81	    return readEntities(body);
 82	  } catch (error) {
 83	    if (timedOut) throw new Error("Search is taking too long. Try again.");
 84	    if (signal.aborted) throw error;
 85	    if (error instanceof TypeError || error instanceof SyntaxError) {
 86	      throw new Error(
 87	        "Couldn’t connect to search. Check your connection and try again.",
 88	      );
 89	    }
 90	    throw error;
 91	  } finally {
 92	    clearTimeout(timeout);
 93	    signal.removeEventListener("abort", cancel);
 94	  }
 95	}
 96	
 97	export function entityType(entity: Entity): string {
 98	  if (entity.kind === "MP") return "MP";
 99	  return `Funder: ${funderKindLabel(entity.funderKind)}`;
100	}
101	
102	export function funderKindLabel(value: string | null): string {
103	  const kind = value?.trim();
104	  if (!kind || kind.toLowerCase() === "not specified") return "Unclassified";
105	  if (kind.toLowerCase() === "individual") return "Individual";
106	  if (kind.toLowerCase() === "company") return "Company";
107	  if (kind.toLowerCase() === "trade union") return "Trade union";
108	  return kind;
109	}
110	
111	export function funderKindIcon(value: string | null) {
112	  switch (funderKindLabel(value).toLowerCase()) {
113	    case "individual":
114	      return "person";
115	    case "company":
116	      return "building";
117	    case "trade union":
118	      return "group";
119	    case "unclassified":
120	      return "question";
121	    default:
122	      return "tag";
123	  }
124	}
125	
126	// Plain-text segments keep source names intact and never interpret names or
127	// user input as markup. Matching here only highlights; it never changes rank.
128	export function highlightName(name: string, term: string) {
129	  const tokens = [...new Set(term.trim().split(/\s+/u).filter(Boolean))]
130	    .sort((a, b) => b.length - a.length)
131	    .map((token) => token.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
132	  if (!tokens.length) return [{ text: name, matched: false }];
133	  const pattern = new RegExp(tokens.join("|"), "giu");
134	  const segments: { text: string; matched: boolean }[] = [];
135	  let position = 0;
136	  for (const match of name.matchAll(pattern)) {
137	    const start = match.index;
138	    if (start > position)
139	      segments.push({ text: name.slice(position, start), matched: false });
140	    segments.push({ text: match[0], matched: true });
141	    position = start + match[0].length;
142	  }
143	  if (position < name.length)
144	    segments.push({ text: name.slice(position), matched: false });
145	  return segments;
146	}

