  1	<script lang="ts">
  2	  import Icon from "./lib/Icon.svelte";
  3	  import EntityIndicator from "./lib/EntityIndicator.svelte";
  4	  import {
  5	    highlightName,
  6	    readStrictness,
  7	    searchConfiguration,
  8	    searchEntities,
  9	    type Entity,
 10	  } from "./lib/search";
 11	
 12	  type SearchState =
 13	    | { status: "idle" }
 14	    | { status: "loading"; term: string }
 15	    | { status: "success"; term: string; entities: Entity[] }
 16	    | { status: "error"; term: string; message: string };
 17	
 18	  let query = $state(new URL(window.location.href).searchParams.get("q") ?? "");
 19	  let strictness = $state(
 20	    readStrictness(
 21	      new URL(window.location.href).searchParams.get("strictness"),
 22	    ),
 23	  );
 24	  let composing = $state(false);
 25	  let attempt = $state(0);
 26	  let input: HTMLInputElement;
 27	  let searchState = $state<SearchState>({ status: "idle" });
 28	  const term = $derived(query.trim());
 29	  const charactersNeeded = $derived(
 30	    Math.max(0, searchConfiguration.minimumCharacters - [...term].length),
 31	  );
 32	  const announcement = $derived(
 33	    searchState.status === "loading"
