   289	          <span class="state-icon"><Icon name="search" size={24} /></span>
   290	          <h2>No matches for “{searchState.term}”</h2>
   291	          <p>Try a surname, a shorter company name, or a different spelling.</p>
   292	          <button
   293	            class="text-button"
   294	            type="button"
   295	            onclick={() => {
   296	              input.focus();
   297	              input.select();
   298	            }}>Edit your search</button
   299	          >
   300	        </div>
   301	      {:else}
   302	        <div class="results-heading">
   303	          <h2>
   304	            {searchState.entities.length}
   305	            {searchState.entities.length === 1 ? "result" : "results"} shown
   306	          </h2>
   307	          <span>Best matches first</span>
   308	        </div>
   309	        <div class="entity-legend" aria-label="Entity icon key">
   310	          <span><Icon name="parliament" size={16} />MP</span>
   311	          <span><Icon name="coin" size={16} />Funder</span>
   312	        </div>
   313	        <ul class="results-list">
   314	          {#each searchState.entities as entity}
   315	            <li class="entity-row">
   316	              <EntityIndicator {entity} />
   317	              <span class="entity-name"
   318	                >{#each highlightName(entity.name, searchState.term) as part}{#if part.matched}<mark
   319	                      >{part.text}</mark
   320	                    >{:else}{part.text}{/if}{/each}</span
   321	              >
   322	              {#if entity.kind === "Funder"}
   323	                <EntityIndicator {entity} detail="kind" />
   324	              {/if}
   325	            </li>
   326	          {/each}
   327	        </ul>
   328	        {#if atLimit(searchState.entities)}<p class="results-note">
   329	            Showing the closest matches. Add more of the name to narrow your
   330	            search.
   331	          </p>{/if}
   332	      {/if}
   333	    </section>
   334	  </main>
   335	
   336	  <footer class="app-footer">
   337	    <span>Contains Parliamentary information.</span><a
   338	      href="https://www.parliament.uk/site-information/copyright-parliament/open-parliament-licence/"
   339	      target="_blank"
   340	      rel="noreferrer">Open Parliament Licence</a
   341	    >
   342	  </footer>
   343	</div>
"}
